40	
41	    private static final int EMAIL_POINTS = 2;
42	
43	    private static final int UNIQUE_NAME_POINTS = 1;
44	
45	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
46	
47	    private static final int TENURE_POINTS = 3;
48	
49	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
50	
51	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
52	
53	    private MembershipLevel() {
54	    }
55	
56	    /**
57	     * The owner's membership level, from 1 to 4, banded from {@link #points} and then capped at one
58	     * above the maximum level among their existing household members (see {@link #householdLevelCap}).
59	     */
60	    public static int of(Owner owner, OwnerRepository ownerRepository) {
61	        int level = level(points(owner, ownerRepository));
62	        Integer cap = householdLevelCap(owner, ownerRepository);
63	        if (cap != null && level > cap) {
64	            return cap;
65	        }
66	        return level;
67	    }
68	
