70	    public static int points(Owner owner, OwnerRepository ownerRepository) {
71	        int points = 0;
72	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
73	            points += EMAIL_POINTS;
74	        }
75	        Integer namesakeCount = owner.getNamesakeCount();
76	        if (namesakeCount != null && namesakeCount == 0) {
77	            points += UNIQUE_NAME_POINTS;
78	        }
79	        if (householdSize(owner, ownerRepository) >= LARGE_HOUSEHOLD_SIZE) {
80	            points += LARGE_HOUSEHOLD_POINTS;
81	        }
